import Foundation
import Testing
@testable import PixlLibrary

/// The stage 2a, milestone 2 golden vectors (`stage2a.jsonl`): `subtract`, `repeat`, `chip`, `weakNegative`,
/// `whyFacts` and `plan`. Generated by the Android repo's `./gradlew :brain:generateGolden`, copied here unchanged.
/// The README beside the file says how each `fn` is replayed (note: `closestOfSeeds` of a `plan` line is a key of
/// `in`, a sibling of `request`, not a key inside it).
@Suite("Brain stage 2a milestone 2 golden vectors (brainMatchesAndroid)")
struct BrainMilestone2GoldenTests {
    typealias G = BrainGoldenTests

    /// The candidates of this file carry two more fields; a file that lacks them (every earlier one) gives 0.
    static func candidates(_ input: BrainJson.Value) -> [Candidate] {
        G.array(input, "candidates").map {
            Candidate(rid: G.long($0, "rid"), aid: G.long($0, "aid"), albumKey: G.long($0, "albumKey"),
                      inLibrary: G.bool($0, "inLibrary"), liked: G.bool($0, "liked"),
                      fromArtistRadio: G.bool($0, "fromArtistRadio"), boostLn: G.double($0, "boostLn"),
                      fromSimilarArtist: G.bool($0, "fromSimilarArtist"), actr: $0["actr"]?.doubleValue ?? 0.0)
        }
    }

    @Test func stage2aMatchesAndroid() throws {
        var report = G.Report(file: "stage2a.jsonl")
        var counts: [String: Int] = [:]
        for c in try G.cases("stage2a.jsonl") {
            counts[c.fn, default: 0] += 1
            let i = c.input
            switch c.fn {
            case "subtract":
                let now = G.long(i, "nowMs")
                let events = G.events(i, "events")
                var state = Replay.rebuild(events, facts: G.facts(i), nowMs: now)
                for index in G.array(i, "indices") {
                    let e = events[Int(index.bareLong ?? 0)]
                    let g = Reward.grade(e, Reward.Context(pastCompletions: 0, skipStreak: 0))
                    Affinity.subtract(&state, e, g, tMs: e.startedAtMs > now ? now : e.startedAtMs)
                }
                _ = state.drainTouched()
                let text = G.dump(state)
                report.record(c, c.matches { $0.raw("state", text) })
            case "repeat":
                var history = RepeatActivation.History()
                let times = G.longs(i, "times")
                let weights = G.array(i, "weights").map { $0.doubleValue ?? .nan }
                for k in times.indices { history.add(times[k], weights[k]) }
                let now = G.long(i, "nowMs")
                let b = RepeatActivation.b(history, nowMs: now)
                let feature = RepeatActivation.feature(history, nowMs: now)
                report.record(c, c.matches {
                    $0.int("count", history.count); $0.double("aggC", history.aggC); $0.double("aggT", history.aggT)
                    $0.double("b", b); $0.double("feature", feature)
                })
            case "chip":
                let chip = ChipLabels.classify(G.string(i, "label"))
                report.record(c, c.matches { $0.string("kind", chip.kind.rawValue); $0.string("key", chip.key) })
            case "weakNegative":
                var state = SessionState(nuStart: Session.nuDefault)
                let rids = G.longs(i, "rids")
                let aids = G.longs(i, "aids")
                for k in rids.indices { Session.weakNegative(&state, rid: rids[k], aid: aids[k]) }
                let text = state.encode()
                report.record(c, c.matches { $0.raw("sessionState", text) })
            case "whyFacts":
                let facts = WhyFacts.pick(
                    artistPlays: Int(G.int(i, "artistPlays")), artistFinished: Int(G.int(i, "artistFinished")),
                    trackFinished: Int(G.int(i, "trackFinished")), year: Int(G.int(i, "year")))
                report.record(c, c.matches {
                    $0.beginArray("facts")
                    for f in facts {
                        $0.beginArray(); $0.stringItem(f.key); $0.intItem(f.a); $0.intItem(f.b); $0.endArray()
                    }
                    $0.endArray()
                })
            case "plan":
                guard let r = i["request"] else {
                    report.record(c, false)
                    continue
                }
                let seeds = G.seeds(i)
                let candidates = Self.candidates(i)
                let affinity = Replay.rebuild(G.events(i, "history"), facts: G.facts(i), nowMs: G.long(i, "nowMs"))
                var session = SessionState(nuStart: Session.nuDefault)
                session.seed = seeds[0].seedRid
                session.seedAid = seeds[0].seedAid
                session.seedKind = Session.seedStationArtist
                let graph = StationPlanner.buildGraph(seeds: seeds, candidates: candidates, session: session)
                let request = StationPlanner.Request(
                    mode: G.int(r, "mode"), count: Int(G.int(r, "count")), candidates: candidates, seeds: seeds,
                    nowMs: G.long(r, "nowMs"), tzOffsetMin: G.int(r, "tzOffsetMin"),
                    nuMultiplier: G.double(r, "nuMultiplier"), tieSeed: G.long(r, "tieSeed"),
                    excludedRids: Set(G.longs(r, "excludedRids")), bridge: G.bool(r, "bridge"),
                    finite: G.bool(r, "finite"), closestOfSeeds: G.bool(i, "closestOfSeeds"))
                let plan = StationPlanner.plan(request, affinity: affinity, session: session, graph: graph)
                report.record(c, c.matches { G.writePlan(&$0, "plan", plan) })
            default:
                report.record(c, false)
            }
        }
        report.verify(atLeast: 300)
        #expect(counts["subtract"] == 8)
        #expect(counts["repeat"] == 60)
        #expect(counts["chip"] == 30)
        #expect(counts["weakNegative"] == 6)
        #expect(counts["whyFacts"] == 256)
        #expect(counts["plan"] == 8)
    }

    @Test func aPlanOfSimilarArtistsPicksUnderTheSimArm() throws {
        var sim = 0
        for c in try G.cases("stage2a.jsonl") where c.fn == "plan" {
            sim += c.line.components(separatedBy: "\"arm\":\(Arm.sim)").count - 1
        }
        #expect(sim > 0, "no plan in the file picked a track from a similar artist")
    }
}
